"""Build one transactional SQL Editor script from canonical migrations."""
from pathlib import Path
import json
import re

ROOT = Path(__file__).resolve().parents[1]
BASE = ROOT / "supabase"


def build():
    config = json.loads((ROOT / "ml/config.json").read_text(encoding="utf-8"))
    names = config["features"]
    groups = json.loads((ROOT / "ml/shap_groups.json").read_text(encoding="utf-8"))
    assert len(names) == len(set(names)) == 127
    literal = lambda value: "'" + value.replace("'", "''") + "'"
    contract = (
        "-- Generated by supabase/build_setup.py from ml/config.json.\n"
        "insert into app_private.feature_contracts(dataset_version,feature_names,model_sha256,explanation_version,group_ids) values ("
        + literal(config["dataset_version"]) + ", array[\n  "
        + ",\n  ".join(map(literal, names)) + "\n],"
        + literal(groups["model_sha256"]) + "," + literal(groups["version"]) + ",array["
        + ",".join(literal(g["id"]) for g in groups["groups"]) + "]);\n"
    )
    (BASE / "migrations/20261018000550_feature_contract.sql").write_text(contract, encoding="utf-8")
    migrations = sorted((BASE / "migrations").glob("*.sql"))
    foundation = migrations[0].read_text(encoding="utf-8")
    # Existing six-table foundation is retained. A partially applied foundation
    # is rejected instead of silently filling a drifted schema.
    wrapper = """-- Generated by build_setup.py. Run ALL of this script ONCE in SQL Editor.
-- Supports a fresh project OR the previously applied six-table foundation.
-- Existing data is retained. Any failure rolls back this whole setup.
begin;
do $install$
declare v_count integer;
begin
  if to_regclass('public.staff_members') is not null then
    raise exception 'Workspace already installed; use new versioned migrations, not setup.sql';
  end if;
  select count(*) into v_count from information_schema.tables where table_schema='public'
    and table_name in ('customers','prediction_runs','customer_snapshots','churn_predictions','prediction_contexts','retention_cases');
  if v_count=0 then
    execute $foundation$\n""" + foundation + """\n$foundation$;
  elsif v_count<>6 then
    raise exception 'Partial foundation found. Stop and inspect schema before installing';
  end if;
end $install$;
"""
    sections = [wrapper]
    for path in migrations[1:]:
        sections += ["\n-- Source: " + path.name + "\n", path.read_text(encoding="utf-8")]
    sections.append("\nnotify pgrst, 'reload schema';\ncommit;\n")
    (BASE / "setup.sql").write_text("".join(sections), encoding="utf-8")
    # Also support users who already installed the previous full workspace.
    changed = ["app_private.cancel_pending", "public.retention_save_draft", "public.retention_review_message",
        "public.retention_request_recommendation", "public.retention_pending_jobs", "public.retention_complete_job", "public.retention_fail_job",
        "public.retention_schedule_reminder", "public.retention_complete_task", "public.retention_request_support",
        "public.retention_update_case", "public.retention_record_outcome", "public.retention_record_cost",
        "public.retention_portal_send", "public.retention_opt_out", "public.retention_set_demo_consent",
        "public.retention_worker_context"]
    upgrade = ["""-- Generated by build_setup.py. Only for an ALREADY installed 25-table workspace.
-- Keeps customers, predictions, cases, messages, approvals, outcomes and request keys.
-- Removes only the obsolete AI retry/lease metadata; running AI jobs become queued.
begin;
do $$ declare f record; begin
  if to_regclass('public.staff_members') is null then raise exception 'Use setup.sql for a new project'; end if;
  for f in select p.oid from pg_proc p where p.pronamespace='public'::regnamespace
    and p.proname in ('retention_claim_job','retention_fail_job','retention_complete_job','retention_worker_context','retention_request_recommendation','retention_pending_jobs') loop
    execute format('drop function %s',f.oid::regprocedure);
  end loop;
end $$;
alter table public.automation_jobs
  add column if not exists rewrite_instructions text check(length(rewrite_instructions)<=2000),
  add column if not exists rewrite_source_text text check(length(rewrite_source_text)<=10000);
drop index if exists public.jobs_worker_idx;
alter table public.automation_jobs drop constraint if exists automation_jobs_status_check;
update public.automation_jobs set status='queued' where status='running';
alter table public.automation_jobs
  drop column if exists attempt_count,
  drop column if exists next_attempt_at,
  drop column if exists lease_token,
  drop column if exists lease_until,
  drop column if exists error_code,
  add constraint automation_jobs_status_check check (status in ('queued','completed','failed','cancelled'));
create index jobs_worker_idx on public.automation_jobs(status,created_at);
"""]
    sources = "\n".join(p.read_text(encoding="utf-8") for p in migrations)
    for name in changed:
        match = re.search(r"create function " + re.escape(name) + r"\(.*?end \$\$;", sources, re.S)
        assert match, name
        upgrade.append(match.group().replace("create function", "create or replace function", 1) + "\n")
    upgrade.append((BASE / "migrations/20261018091216_typed_ai_queues_demo_portal.sql").read_text(encoding="utf-8"))
    upgrade.append((BASE / "migrations/20261018093807_ai_request_progress_and_usage.sql").read_text(encoding="utf-8"))
    upgrade.append("""do $$ declare f record; begin
  for f in select p.oid,p.proname from pg_proc p where p.pronamespace='public'::regnamespace
    and p.proname like 'retention\\_%' escape '\\' loop
    execute format('revoke all on function %s from public,anon,authenticated,service_role',f.oid::regprocedure);
    execute format('grant execute on function %s to %I',f.oid::regprocedure,
      case when f.proname in ('retention_claim_delivery','retention_deliver_mock','retention_fail_delivery',
        'retention_claim_ai_request','retention_pending_jobs','retention_complete_job','retention_fail_job','retention_worker_context','retention_process_followups',
        'retention_process_support','retention_ingest_prediction','retention_set_demo_consent')
        then 'service_role' else 'authenticated' end);
  end loop;
end $$;
notify pgrst, 'reload schema';
commit;
""")
    (BASE / "upgrade_lean.sql").write_text("\n".join(upgrade), encoding="utf-8")
    print(f"Built setup.sql from {len(migrations)} migrations; 127-feature whitelist included.")


if __name__ == "__main__":
    build()
